solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <set>
#include <string>
#include <vector>

struct Write { std::uint64_t rip; std::uint64_t address; std::uint32_t size; std::string operand; };

std::vector<std::uint64_t> whatWrites(const std::vector<Write>& trace, std::uint64_t address, std::uint32_t size)
{
    std::vector<std::uint64_t> rips;
    for (const Write& w : trace)
    {
        const bool overlaps{ w.address < address + size && address < w.address + w.size };
        if (overlaps && std::find(rips.begin(), rips.end(), w.rip) == rips.end()) rips.push_back(w.rip);
    }
    return rips;
}

std::optional<std::int64_t> displacementOf(const std::string& operand)
{
    const std::size_t open{ operand.find('[') }, close{ operand.find(']') };
    if (open == std::string::npos || close == std::string::npos || close < open) return std::nullopt;
    const std::string inside{ operand.substr(open + 1, close - open - 1) };
    const std::size_t hex{ inside.find("0x") };
    if (hex == std::string::npos) return 0;
    const std::int64_t value{ static_cast<std::int64_t>(std::stoull(inside.substr(hex + 2), nullptr, 16)) };
    return (hex > 0 && inside[hex - 1] == '-') ? -value : value;
}

std::vector<std::uint64_t> objectCandidates(const std::vector<Write>& trace, std::uint64_t address)
{
    std::set<std::uint64_t> starts;
    for (const Write& w : trace)
    {
        if (w.address != address || w.operand.find('*') != std::string::npos) continue;
        if (const auto d{ displacementOf(w.operand) }) starts.insert(address - static_cast<std::uint64_t>(*d));
    }
    return { starts.begin(), starts.end() };
}

unitTests:
using U = std::vector<std::uint64_t>;
static std::vector<Write> trace()
{
    return {
        { 0x14000201A, 0x2C40961C, 4, "dword ptr [rbx+0x1C]" },     // takeDamage: health -= amount
        { 0x140003300, 0x2C409600, 8, "qword ptr [rcx]" },          // constructor: vtable pointer
        { 0x14000201A, 0x2C40961C, 4, "dword ptr [rbx+0x1C]" },
        { 0x140004410, 0x2C409618, 8, "qword ptr [rdi+0x18]" },     // an 8-byte write that covers health too
        { 0x140005000, 0x2C40961C, 4, "dword ptr [rax+rcx*4+0x10]" },
        { 0x140006000, 0x2C40961C, 4, "dword ptr [rdx+0x2C]" },     // another struct that embeds the player at +0x10
    };
}

TEST("what writes to health") {
    CHECK_EQ(whatWrites(trace(), 0x2C40961C, 4), (U{ 0x14000201A, 0x140004410, 0x140005000, 0x140006000 }));
    CHECK_EQ(whatWrites(trace(), 0x2C409600, 1), (U{ 0x140003300 }));
    CHECK(whatWrites(trace(), 0x2C409700, 4).empty());
}
TEST("displacements") {
    CHECK_EQ(displacementOf("dword ptr [rbx+0x1C]").value_or(-1), 0x1C);
    CHECK_EQ(displacementOf("[rax-0x8]").value_or(-1), -8);
    CHECK_EQ(displacementOf("qword ptr [rcx]").value_or(-1), 0);
    CHECK_EQ(displacementOf("[rax+rcx*4+0x10]").value_or(-1), 0x10);
    CHECK(!displacementOf("eax").has_value());
}
TEST("where the object starts") {
    CHECK_EQ(objectCandidates(trace(), 0x2C40961C), (U{ 0x2C4095F0, 0x2C409600 }));
    CHECK(objectCandidates(trace(), 0x2C409610).empty());
}

